// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("totals a few small orders", () -> {
        eq(totalCents(List.of(new Order("a", 100), new Order("b", 250), new Order("c", 5))), 355);
    });
    test("an empty list totals 0 and averages 0.0", () -> {
        eq(totalCents(List.of()), 0);
        eq(averageCents(List.of()), 0.0);
    });
    test("refunds count as negative cents", () -> {
        eq(totalCents(List.of(new Order("a", 500), new Order("r", -200))), 300);
        eq(averageCents(List.of(new Order("a", 500), new Order("r", -200))), 150.0);
    });
    test("the average keeps its fraction", () -> {
        eq(averageCents(List.of(new Order("a", 100), new Order("b", 201))), 150.5);
        approx(averageCents(List.of(new Order("a", 1), new Order("b", 1), new Order("c", 2))), 4.0 / 3, 1e-9);
    });
    test("a big month totals without wrapping around", () -> {
        var big = new Order("x", 1_500_000_000);
        eq(totalCents(List.of(big, big, big)), 4_500_000_000L);
    });
    test("big orders average correctly", () -> {
        var big = new Order("x", 2_000_000_000);
        eq(averageCents(List.of(big, big)), 2.0e9);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    var results = IntStream.range(0, 25).boxed().toList();
    test("page 1 holds the first results", () -> {
        eq(page(results, 1, 10).items(), IntStream.range(0, 10).boxed().toList());
        eq(page(results, 2, 10).items(), IntStream.range(10, 20).boxed().toList());
    });
    test("the last page holds the remainder", () -> {
        eq(page(results, 3, 10).items(), List.of(20, 21, 22, 23, 24));
    });
    test("a partial last page counts as a page", () -> {
        eq(page(results, 1, 10).totalPages(), 3);
        ok(page(results, 2, 10).hasNext(), "page 2 of 3 has a next page");
        ok(!page(results, 3, 10).hasNext(), "page 3 of 3 has no next page");
    });
    test("an exact multiple has no extra page", () -> {
        var twenty = results.subList(0, 20);
        eq(page(twenty, 2, 10).totalPages(), 2);
        ok(!page(twenty, 2, 10).hasNext(), "page 2 of 2 has no next page");
        eq(page(twenty, 3, 10).items(), List.of());
    });
    test("no results means no pages", () -> {
        var p = page(List.<Integer>of(), 1, 10);
        eq(p.items(), List.of());
        eq(p.totalPages(), 0);
        ok(!p.hasNext(), "nothing next");
    });
    test("page and size start at 1", () -> {
        raises(IllegalArgumentException.class, () -> page(results, 0, 10));
        raises(IllegalArgumentException.class, () -> page(results, 1, 0));
        eq(page(results, 25, 1).items(), List.of(24));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("counts a small customer's paid orders built in code", () -> {
        eq(countPaid(List.of(new Order("o1", 7, "PAID"), new Order("o2", 7, "NEW"), new Order("o3", 8, "PAID")), 7), 1);
    });
    test("counts a large customer's paid orders", () -> {
        var orders = List.of(new Order("o1", 4521, "PAID"), new Order("o2", 4521, "PAID"), new Order("o3", 4521, "NEW"));
        eq(countPaid(orders, 4521), 2);
        eq(countPaid(orders, Integer.valueOf("4521")), 2);
    });
    test("counts orders parsed from CSV lines", () -> {
        var orders = List.of(parse("o1, 7, PAID"), parse("o2,7,PAID"), parse("o3, 7 ,REFUNDED"));
        eq(countPaid(orders, 7), 2);
    });
    test("ignores other customers and statuses", () -> {
        var orders = List.of(new Order("o1", 1, "NEW"), new Order("o2", 2, "PAID"), new Order("o3", 1, "paid"));
        eq(countPaid(orders, 1), 0);
        eq(countPaid(List.of(), 1), 0);
    });
    test("parse trims every field", () -> {
        eq(parse(" o9 , 12 , NEW "), new Order("o9", 12, "NEW"));
        eq(parse("o1,100000,PAID").customerId(), 100000);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("a new user starts with the default tag", () -> {
        eq(tagsOf(create("ada")), List.of("new"));
    });
    test("tagging one new user does not tag the next one", () -> {
        var ada = create("ada");
        tag(ada, "vip");
        eq(tagsOf(ada), List.of("new", "vip"));
        eq(tagsOf(create("bob")), List.of("new"));
    });
    test("users built from one list do not share tags", () -> {
        var batch = new ArrayList<>(List.of("imported"));
        var a = create("a", batch);
        var b = create("b", batch);
        tag(a, "x");
        eq(tagsOf(b), List.of("imported"));
        batch.add("late");
        eq(tagsOf(a), List.of("imported", "x"));
    });
    test("an immutable list is a fine starting point", () -> {
        var c = create("c", List.of("t"));
        tag(c, "u");
        eq(tagsOf(c), List.of("t", "u"));
    });
    test("tagsOf is an unmodifiable snapshot", () -> {
        var u = create("u", List.of("b", "a"));
        var snapshot = tagsOf(u);
        raises(UnsupportedOperationException.class, () -> snapshot.sort(null));
        tag(u, "c");
        eq(snapshot, List.of("b", "a"));
        eq(tagsOf(u), List.of("b", "a", "c"));
    });
    test("a tag is added once", () -> {
        var u = create("u");
        tag(u, "x");
        tag(u, "x");
        tag(u, "new");
        eq(tagsOf(u), List.of("new", "x"));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("equal ignoring case and spaces, also through Object", () -> {
        var a = new Email("A@x.io");
        var b = new Email(" a@X.IO ");
        ok(a.equals(b), "a.equals(b)");
        Object o = b;
        ok(a.equals(o), "a.equals((Object) b)");
    });
    test("equal emails have equal hash codes", () -> {
        eq(new Email("Ada@X.com").hashCode(), new Email("ada@x.com ").hashCode());
    });
    test("a set keeps one per address", () -> {
        eq(uniqueRecipients(List.of("ada@x.com", "Ada@X.com", " ada@x.com ")), 1);
        eq(uniqueRecipients(List.of("ada@x.com", "bob@x.com", "BOB@X.COM")), 2);
    });
    test("contains finds an address written differently", () -> {
        ok(isSubscribed(List.of(new Email("Bob@y.org")), "bob@y.org"), "found in a List");
        ok(isSubscribed(Set.of(new Email("bob@y.org")), "BOB@Y.ORG "), "found in a Set");
    });
    test("different addresses stay different", () -> {
        var a = new Email("a@x.io");
        ok(!a.equals(new Email("b@x.io")), "different address");
        ok(!a.equals((Object) "a@x.io"), "not equal to a String");
        ok(!a.equals((Object) null), "not equal to null");
        ok(!isSubscribed(List.of(a), "b@x.io"), "not subscribed");
    });
    test("works as a HashMap key", () -> {
        var opens = new HashMap<Email, Integer>();
        opens.merge(new Email("Ada@X.com"), 1, Integer::sum);
        opens.merge(new Email("ada@x.com"), 1, Integer::sum);
        eq(opens.size(), 1);
        eq(opens.get(new Email(" ADA@x.com")), 2);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

