public static void main(String[] args) {
    test("removes a lone expired session and keeps the rest in order", () -> {
        var s = new ArrayList<>(List.of(new Session(1, 9), new Session(2, 3), new Session(3, 8)));
        removeExpired(s, 5);
        eq(s, List.of(new Session(1, 9), new Session(3, 8)));
    });
    test("a session expiring exactly now is expired", () -> {
        var s = new ArrayList<>(List.of(new Session(1, 5), new Session(2, 6)));
        removeExpired(s, 5);
        eq(s, List.of(new Session(2, 6)));
    });
    test("removes expired sessions that sit side by side", () -> {
        var s = new ArrayList<>(List.of(new Session(1, 1), new Session(2, 2), new Session(3, 9),
            new Session(4, 3), new Session(5, 4)));
        removeExpired(s, 5);
        eq(s, List.of(new Session(3, 9)));
    });
    test("removes everything when everything expired", () -> {
        var s = new ArrayList<>(List.of(new Session(1, 1), new Session(2, 1), new Session(3, 1)));
        removeExpired(s, 1);
        eq(s, List.of());
    });
    test("logout removes that user id, not the one at that index", () -> {
        var ids = new ArrayList<>(List.of(10, 3, 7, 1));
        logout(ids, 3);
        eq(ids, List.of(10, 7, 1));
        logout(ids, 1);
        eq(ids, List.of(10, 7));
    });
    test("logout of an id that is not active changes nothing", () -> {
        var ids = new ArrayList<>(List.of(1, 2));
        logout(ids, 42);
        eq(ids, List.of(1, 2));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("a line total is price times quantity", () -> {
        eq(lineTotal("2.50", 3).toPlainString(), "7.50");
        eq(lineTotal("19.99", 0), BigDecimal.ZERO);
    });
    test("tax rounds half up to cents", () -> {
        eq(tax(new BigDecimal("10.50"), "0.05"), new BigDecimal("0.53"));
        eq(tax(new BigDecimal("0.10"), "0.05"), new BigDecimal("0.01"));
        eq(tax(new BigDecimal("10.50"), "0.05").scale(), 2);
    });
    test("tax that is not on a half rounds to the nearest cent", () -> {
        eq(tax(new BigDecimal("19.99"), "0.08").toPlainString(), "1.60");
        eq(tax(new BigDecimal("10.00"), "0.0726").toPlainString(), "0.73");
        eq(tax(new BigDecimal("10.00"), "0.0721").toPlainString(), "0.72");
    });
    test("any zero total is free, whatever its scale", () -> {
        ok(isFree(BigDecimal.ZERO), "0");
        ok(isFree(new BigDecimal("0.00")), "0.00");
        ok(isFree(lineTotal("0.00", 2)), "0.00 x 2");
        ok(isFree(new BigDecimal("5.00").subtract(new BigDecimal("5.00"))), "5.00 - 5.00");
    });
    test("a non-zero total is not free", () -> {
        ok(!isFree(new BigDecimal("0.01")), "0.01");
        ok(!isFree(new BigDecimal("-1")), "-1");
    });
    test("distinct prices compare by value, not by scale", () -> {
        eq(distinctPrices(List.of(new BigDecimal("2.5"), new BigDecimal("2.50"), new BigDecimal("3"))), 2);
        eq(distinctPrices(List.of(new BigDecimal("1.00"), new BigDecimal("1.0"), new BigDecimal("1"))), 1);
        eq(distinctPrices(List.of()), 0);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    var ny = ZoneId.of("America/New_York");
    var tokyo = ZoneId.of("Asia/Tokyo");
    test("an evening order in New York is reported on its local day", () -> {
        eq(reportDay(Instant.parse("2024-03-06T01:30:00Z"), ny), LocalDate.of(2024, 3, 5));
    });
    test("a breakfast order in Tokyo is reported on its local day", () -> {
        eq(reportDay(Instant.parse("2024-03-05T20:00:00Z"), tokyo), LocalDate.of(2024, 3, 6));
    });
    test("a midday order is on the same day everywhere", () -> {
        eq(reportDay(Instant.parse("2024-03-05T12:00:00Z"), ZoneOffset.UTC), LocalDate.of(2024, 3, 5));
        eq(reportDay(Instant.parse("2024-03-05T16:00:00Z"), ny), LocalDate.of(2024, 3, 5));
    });
    test("the next reminder on an ordinary day", () -> {
        var last = ZonedDateTime.of(2024, 6, 1, 9, 0, 0, 0, ny);
        eq(nextReminder(last), ZonedDateTime.of(2024, 6, 2, 9, 0, 0, 0, ny));
    });
    test("the next reminder keeps 9:00 across the March change", () -> {
        var last = ZonedDateTime.of(2024, 3, 9, 9, 0, 0, 0, ny);
        eq(nextReminder(last).toLocalDateTime(), LocalDateTime.of(2024, 3, 10, 9, 0));
    });
    test("the next reminder keeps 9:00 across the November change", () -> {
        var last = ZonedDateTime.of(2024, 11, 2, 9, 0, 0, 0, ny);
        eq(nextReminder(last).toLocalDateTime(), LocalDateTime.of(2024, 11, 3, 9, 0));
        eq(nextReminder(last).getZone(), ny);
    });
    test("labels use the calendar year", () -> {
        eq(label(LocalDate.of(2024, 6, 1)), "2024-06-01");
        eq(label(LocalDate.of(2024, 12, 30)), "2024-12-30");
        eq(label(LocalDate.of(2027, 1, 1)), "2027-01-01");
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

